mapper.sql:
attempt_id=#{attemptId} AND project_id=#{projectId} AND created_by=#{userId} AND status='RUNNING'
AND lease_owner=#{workerId} AND lease_generation=#{generation} AND revision=#{expectedRevision}
AND lease_expires_at>#{now} AND execution_deadline>#{now}
AND lease_expires_at>UTC_TIMESTAMP(6) AND execution_deadline>UTC_TIMESTAMP(6)

mapper.update:
UPDATE processing_attempt SET command_ref=#{commandRef},result_ref=#{resultRef},write_intent=#{writeIntent},
  revision=revision+1,updated_at=#{now}
WHERE  AND write_intent IS NULL AND result_ref IS NULL

UPDATE parse_version SET parse_status='FAILED',failure_manifest=#{failureManifest}
WHERE source_version=#{sourceVersion} AND parse_version=#{parseVersion} AND parse_status IN ('QUEUED','PROCESSING')
  AND artifact_key IS NULL AND content_sha256 IS NULL

mapper.select:
SELECT COUNT(*) FROM source_chunk c JOIN chunk_node n ON n.tenant_id=c.tenant_id AND n.source_version=c.source_version
  AND n.parse_version=c.parse_version AND n.chunk_id=c.chunk_id AND n.node_id=c.node_id
WHERE c.source_version=#{sourceVersion} AND c.parse_version=#{parseVersion}
